// ---------------------------------------------------------------------------
// Hook wrappers — called unconditionally to satisfy React rules of hooks.
// Return meaningful data only when applicable based on tokenResolution.
// ---------------------------------------------------------------------------

function useNativeTokenData(
  chainId: Hex,
  resolution: TokenResolution,
): PermissionRenderContext['tokenInfo'] {
  const { symbol, decimals } = useSelector(
    (state: MetaMaskReduxState) =>
      getNativeTokenInfo(
        state.metamask.networkConfigurationsByChainId,
        chainId,
      ),
    shallowEqual,
  );
  const imageUrl = CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP[chainId];

  if (resolution.kind !== 'native') {
    return undefined;
  }
  return { symbol, decimals, imageUrl };
}

function useErc20DecimalsResolved(
  permission: { data: Record<string, unknown> },
  chainId: Hex,
  resolution: TokenResolution,
): number | undefined {
  const tokenAddress =
    resolution.kind === 'erc20'
      ? resolution.getTokenAddress(permission)
      : undefined;

  const metadataResult = useAsyncResult(
    () =>
      tokenAddress
        ? fetchErc20DecimalsOrThrow(tokenAddress, chainId)
        : Promise.resolve(undefined),
    [tokenAddress, chainId],
  );

  if (resolution.kind !== 'erc20') {
    return undefined;
  }

  if (metadataResult.status === 'error') {
    throw metadataResult.error;
  }

  return metadataResult.value;
}

// ---------------------------------------------------------------------------
// Element renderer — pure function, no hooks
// ---------------------------------------------------------------------------

function renderAmountField(
  element: AmountField,
  ctx: PermissionRenderContext,
  i18nMap: Record<TranslationKeys, string>,
  index: number,
): React.ReactNode {
  // If the field has getTokenAddress, it's an ERC20 amount
  if (element.getTokenAddress) {
    return (
      <TokenAmountRow
        key={index}
        label={i18nMap[element.labelKey]}
        value={element.getValue(ctx)}
        tokenAddress={element.getTokenAddress(ctx)}
        chainId={ctx.chainId}
        decimals={ctx.tokenInfo?.decimals}
        tooltip={element.tooltip}
      />
    );
  }

  // Native token amount — tokenInfo is guaranteed to be set for native schemas
  const tokenInfo = ctx.tokenInfo as NonNullable<
    PermissionRenderContext['tokenInfo']
  >;
  return (
    <NativeAmountRow
      key={index}
      label={i18nMap[element.labelKey]}
      value={element.getValue(ctx)}
      symbol={tokenInfo.symbol}
      decimals={tokenInfo.decimals}
      imageUrl={tokenInfo.imageUrl}
      tooltip={element.tooltip}
    />
  );
}

function renderElement(
  element: SchemaElement,
  ctx: PermissionRenderContext,
  t: I18nFunction,
  i18nMap: Record<TranslationKeys, string>,
  ownerId: string,
  index: number,
): React.ReactNode {
  // Check visibility predicate
  if ('isVisible' in element && !element.isVisible(ctx)) {
    return null;
  }

  // Skip elements not intended for the confirmation view
  if (!element.includeInViews.includes('confirmation')) {
    return null;
  }

  switch (element.type) {
    case 'amount':
      return renderAmountField(element, ctx, i18nMap, index);

    case 'text': {
      return (
        <ConfirmInfoRow
          key={index}
          label={i18nMap[element.labelKey]}
          tooltip={element.tooltip ? t(element.tooltip) : undefined}
        >
          <Text variant={TextVariant.BodyMd}>
            {translateI18nValue(t, element.getValue(ctx))}
          </Text>
        </ConfirmInfoRow>
      );
    }

    case 'raw-text': {
      return (
        <ConfirmInfoRow
          key={index}
          label={i18nMap[element.labelKey]}
          tooltip={element.tooltip}
        >
          <Text variant={TextVariant.BodyMd}>{element.getValue(ctx)}</Text>
        </ConfirmInfoRow>
      );
    }

    case 'list': {
      return (
        <ConfirmInfoRow
          key={index}
          label={i18nMap[element.labelKey]}
          tooltip={element.tooltip}
        >
          <ul style={{ listStyle: 'disc', paddingLeft: 20 }}>
            {element.getValue(ctx).map((value, valueIndex) => (
              <li key={`${value}-${valueIndex}`}>{t(value)}</li>
            ))}
          </ul>
        </ConfirmInfoRow>
      );
    }

    case 'date': {
      return (
        <DateAndTimeRow
          key={index}
          timestamp={element.getValue(ctx)}
          label={i18nMap[element.labelKey]}
          tooltip={element.tooltip}
        />
      );
    }

    case 'expiry': {
      return <Expiry key={index} expiry={element.getValue(ctx)} />;
    }

    case 'divider': {
      return <ConfirmInfoRowDivider key={index} />;
    }

    case 'justification': {
      const justificationValue = element.getValue(ctx);
      const justificationText =
        typeof justificationValue === 'string'
          ? justificationValue
          : translateI18nValue(t, justificationValue);
      return (
        <ConfirmInfoRow
          key={index}
          label={i18nMap[element.labelKey]}
          tooltip={t('confirmFieldTooltipJustification')}
        >
          <Text variant={TextVariant.BodyMd}>{justificationText}</Text>
        </ConfirmInfoRow>
      );
    }

    case 'account': {
      return <SigningInWithRow key={index} />;
    }

    case 'origin': {
      const origin = ctx.origin ?? '';
      const tooltipMessage = isSnapId(origin)
        ? t('requestFromInfoSnap')
        : t('requestFromInfo');

      return (
        <ConfirmInfoAlertRow
          key={index}
          alertKey={RowAlertKey.RequestFrom}
          ownerId={ownerId}
          label={i18nMap.requestFrom}
          tooltip={tooltipMessage}
        >
          <ConfirmInfoRowUrl url={origin} />
        </ConfirmInfoAlertRow>
      );
    }

    case 'address': {
      const address = element.getValue(ctx);
      if (!address) {
        return null;
      }
      return (
        <ConfirmInfoRow key={index} label={i18nMap[element.labelKey]}>
          <ConfirmInfoRowAddress address={address} chainId={ctx.chainId} />
        </ConfirmInfoRow>
      );
    }

    case 'rule-address': {
      const addresses = element.getValue(ctx);
      if (!addresses?.length) {
        return null;
      }
      return (
        <React.Fragment key={index}>
          <ConfirmInfoRow label={i18nMap[element.labelKey]}>
            <Box
              flexDirection={BoxFlexDirection.Column}
              alignItems={BoxAlignItems.End}
            >
              {addresses.map((address) => (
                <ConfirmInfoRowAddress
                  key={address}
                  address={address}
                  chainId={ctx.chainId}
                />
              ))}
            </Box>
          </ConfirmInfoRow>
        </React.Fragment>
      );
    }

    case 'network': {
      return <NetworkRow key={index} />;
    }

    default: {
      const neverElement: never = element;
      return throwUnhandledPermissionSchemaElement(neverElement);
    }
  }
}

// ---------------------------------------------------------------------------
// Section renderer
// ---------------------------------------------------------------------------

function renderSection(
  section: SchemaSection,
  ctx: PermissionRenderContext,
  t: I18nFunction,
  i18nMap: Record<TranslationKeys, string>,
  ownerId: string,
): React.ReactNode {
  const children = section.elements.map((element, index) =>
    renderElement(element, ctx, t, i18nMap, ownerId, index),
  );

  const hasContent = children.some(
    (child) => child !== null && child !== undefined && child !== false,
  );

  if (!hasContent) {
    return null;
  }

  return (
    <ConfirmInfoSection key={section.testId} data-testid={section.testId}>
      {children}
    </ConfirmInfoSection>
  );
}

// ---------------------------------------------------------------------------
// Main renderer component
// ---------------------------------------------------------------------------

export const PermissionDetailRenderer = ({
  permission,
  expiry,
  chainId,
  origin,
  to,
  ownerId,
  rules,
}: {
  permission: {
    type: string;
    data: Record<string, unknown>;
    justification?: string;
  };
  expiry: number | null;
  chainId: Hex;
  origin: string;
  to?: string;
  ownerId: string;
  rules?: Rule[];
}) => {
  const t = useI18nContext() as I18nFunction;
  const i18nMap = useAdvancedPermissionTranslationsMap();

  const schemaEntry = getPermissionSchemaEntry(permission.type, true);

  const { tokenResolution } = schemaEntry;

  // Hooks must run before any code that can throw (validataion failures),
  // so hook order stays stable if permission data changes between renders.
  const nativeToken = useNativeTokenData(chainId, tokenResolution);
  const erc20Decimals = useErc20DecimalsResolved(
    permission,
    chainId,
    tokenResolution,
  );

  if (schemaEntry.validate) {
    schemaEntry.validate(permission);
  }

  // Build tokenInfo from whichever resolution path is active
  let tokenInfo: PermissionRenderContext['tokenInfo'];
  if (nativeToken) {
    tokenInfo = nativeToken;
  } else if (erc20Decimals === undefined) {
    tokenInfo = undefined;
  } else {
    tokenInfo = { symbol: '', decimals: erc20Decimals };
  }

  const redeemerAddresses = extractAddressesFromRuleByType(
    rules ?? [],
    'redeemer',
  );
  const payeeAddresses = extractAddressesFromRuleByType(rules ?? [], 'payee');

  const ctx: PermissionRenderContext = {
    permission,
    expiry,
    redeemerAddresses,
    payeeAddresses,
    chainId,
    origin,
    to,
    tokenInfo,
    ...(isPermissionDataWithTotalExposure(permission.data)
      ? {
          streamTotalExposure: computeTotalExposureForPermission(
            permission.data,
            expiry,
          ),
        }
      : {}),
  };

  return (
    <>
      {schemaEntry.sections.map((section) =>
        renderSection(section, ctx, t, i18nMap, ownerId),
      )}
    </>
  );
};
